import {noncombatRunning} from './noncombat-policy.js';
import {renderBossChallengeItem} from './boss-challenge-ui.js';
import {equipmentDisplayQuality,equipmentDisplayRarity} from './equipment-display.js';
import {utilityIcon} from './consumable-pixel-art.js';
import {equipmentIcon} from './equipment-art.js';
import {SOCKETS,SLOTS,SLOTNAME,SOCKET_TYPE,RARITY,BUILD,stats,bagCounts,BAG_LIMITS} from './engine.js';
import {icon} from './icons.js';
export const EQUIPMENT_DISPLAY_ORDER=Object.freeze(['weapon','helm','armor','gloves','ring1','ring2','boots','amulet']);
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function filters(s,group){return `<div class="lootFilter"><span>新战利品过滤</span>${(group==='equipment'?[...RARITY.slice(0,4),'传说']:RARITY.slice(0,4)).map((name,q)=>{const enabled=s.lootFilters?.[group]?.includes(q)===true;return `<button class="filterQuality r${q}text" ${q===4?'style="color:#e7bc58"':''} data-loot-filter-group="${group}" data-loot-filter-quality="${q}" aria-pressed="${enabled}" title="${enabled?'停止过滤':'过滤'}新获得的${name}品质战利品">${enabled?'◆':'◇'} ${name}</button>`;}).join('')}<small>仅影响新战斗与离线收获，不影响已有、购买或锻造物品。</small></div>`;}
export function renderInventory(s,ctx){
 const tab=['equipment','items','materials'].includes(ctx.bagTab)?ctx.bagTab:'equipment',slot=SLOTS.includes(ctx.bagSlot)?ctx.bagSlot:'weapon',st=stats(s),counts=bagCounts(s),itemCount=counts.items,matCount=counts.materials;
 const tabs=`<nav class="inventoryTabs" aria-label="行囊分类">${[['equipment','weapon','装备'],['items','potionHeal','道具 / 药剂'],['materials','iron','材料']].map(([key,img,label])=>`<button data-bag-tab="${key}" aria-pressed="${tab===key}">${icon(img)}<span>${label}</span></button>`).join('')}</nav>`;
 if(tab==='items')return `<div class="panelPage inventoryPage">${tabs}<div class="bagHeader"><span>道具与药剂</span><b>${itemCount} / ${BAG_LIMITS.items} 堆叠</b></div>${filters(s,'items')}${renderBossChallengeItem(s)}<div class="utilityInventory">${[['memoryFruit','灵慧之果'],['reforgeToken','重铸印记']].map(([key,name])=>`<div class="utilityItem">${utilityIcon(key==='memoryFruit'?'memoryfruit':key,{size:48})}<strong>${name}</strong><b>×${s.consumables?.[key]||0}</b>${key==='memoryFruit'?`<small>精灵地区特产 · 永久增加3点可分配天赋点</small><button data-wisdom-fruit="${s.consumables?.memoryFruit??0}" ${noncombatRunning(s)||s.activeEncounter&&!s.activeEncounter.done||!(s.consumables?.memoryFruit>0)?'disabled':''}>使用1枚 · 天赋点＋3</button>`:''}</div>`).join('')}</div><p class="subtleText">无品质道具不参与品质过滤</p><div class="inventoryPotions" id="potionPanelHost">${ctx.potionView()}</div></div>`;
 if(tab==='materials')return `<div class="panelPage inventoryPage">${tabs}<div class="bagHeader"><span>材料 · 种类与品质分别堆叠</span><b>${matCount} / ${BAG_LIMITS.materials} 堆叠</b></div>${filters(s,'materials')}<div class="inventoryMaterials">${ctx.materialGrid()}</div></div>`;
 return `<div class="panelPage inventoryPage">${tabs}<div class="inventoryLayout"><div><div class="sectionLabel">当前装备 · 八个栏位</div><div class="equipmentDoll eightSlots"><canvas id="doll" width="160" height="150"></canvas>${EQUIPMENT_DISPLAY_ORDER.map(k=>{const it=s.inventory.find(x=>x.id===s.equip[k]);return `<button data-equip-socket="${k}" class="equipSlot ${it?'r'+equipmentDisplayQuality(it):'emptySlot'} ${it?.set?'setFrame':''}" ${it?'data-item="'+esc(it.id)+'"':''} title="${esc(it?.name||'空栏位')}">${(it?equipmentIcon(it):icon(SOCKET_TYPE[k],'anvil',0))}<small>${SLOTNAME[k]}</small></button>`;}).join('')}</div><div class="equipLegend">E 已装备 · ◆ 锁定 · ✧ 神赐</div></div><div class="bagSection"><div class="equipmentFamilies">${SLOTS.map(k=>`<button data-bag-slot="${k}" aria-pressed="${slot===k}" title="${SLOTNAME[k]} · ${counts.equipment[k]}/${BAG_LIMITS.equipment}">${icon(k)}<small>${SLOTNAME[k]}</small><b>${counts.equipment[k]}/${BAG_LIMITS.equipment}</b></button>`).join('')}</div><div class="bagHeader"><span>${SLOTNAME[slot]}行囊</span><select id="bagSort" aria-label="装备排序">${[['quality','品质'],['slot','部位'],['level','等级']].map(([k,n])=>`<option value="${k}" ${ctx.bagSort===k?'selected':''}>${n}</option>`).join('')}</select><b class="${counts.equipment[slot]>BAG_LIMITS.equipment?'bagOverCapacity':''}">${counts.equipment[slot]} / ${BAG_LIMITS.equipment}</b></div><div class="bagGrid">${ctx.sortedGear().filter(it=>it.slot===slot).map(it=>`<button class="itemCell r${equipmentDisplayQuality(it)} ${it.set?'setFrame':''} ${ctx.selected===it.id?'selected':''}" data-item="${esc(it.id)}" title="${esc(it.name)} · ${equipmentDisplayRarity(it)}">${equipmentIcon(it,{size:32})}${Object.values(s.equip).includes(it.id)?'<span class="equippedDot">E</span>':''}${it.locked?'<span class="lockedDot">◆</span>':''}${it.divine?'<span class="divineDot" title="神赐">✧</span>':''}</button>`).join('')||'<span class="emptyFamily">此类行囊暂无装备</span>'}</div>${filters(s,'equipment')}<small class="bagCapacityNote">每类独立50格 · 戒指共用一袋 · 装备柜不占格<br>背包满后仍会保留已有物品，但无法收入新物品。</small></div><div class="itemDetail">${ctx.itemDetail(s.inventory.find(x=>x.id===ctx.selected))}</div><div class="setLine">${BUILD.map(b=>`${b.name} ${st.count[b.id]||0}/4`).join('　／　')}<br>${BUILD.filter(b=>(st.count[b.id]||0)>=2).map(b=>b.bonus).join('　')||'2件强化核心技能，4件形成完整构筑。'}</div></div></div>`;
}
